    border-color: #0f172a;
}
.btn {
    background: #0f172a;
    color: #ffffff;
    border: none;
    padding: 10px 20px;
    border-radius: 4px;
    font-size: 0.9rem;
    font-weight: 600;
    cursor: pointer;
}
.btn:hover {
    background: #1e293b;
}
footer {
